const payload = $input.first().json;

let cfg = {
  iris_base_url: '',
  llm_model: 'gpt-4o-mini',
  max_cases: 50,
};

try {
  const setConfig = $('Set Config').first().json;
  cfg = {
    iris_base_url: setConfig.iris_base_url ?? '',
    llm_model:     setConfig.llm_model     ?? 'gpt-4o-mini',
    max_cases:     Number(setConfig.max_cases ?? 50),
  };
} catch (e) {
  // allows manual test-run without Set Config context
}

const cases = payload.data ?? payload.cases ?? [];

function norm(v) {
  return String(v ?? '').trim().toLowerCase();
}

function isOpenCase(c) {
  const stateName     = norm(c.state_name ?? c.case_status_name ?? c.case_status);
  const caseCloseDate = String(c.case_close_date ?? '').trim();
  if (stateName === 'open' || stateName === 'reporting') return true;
  if (stateName === 'closed') return false;
  if (caseCloseDate) return false;
  return true;
}

const openCases = cases
  .filter(c => c && c.case_id != null)
  .filter(isOpenCase)
  .slice(0, Math.max(1, Number(cfg.max_cases || 50)));

if (!openCases.length) {
  return [{ json: { status: 'no_open_cases_found' } }];
}

return openCases.map(c => ({
  json: {
    iris_base_url:      cfg.iris_base_url,
    llm_model:          cfg.llm_model,
    case_id:            c.case_id            ?? null,
    case_name:          c.case_name          ?? `Case ${c.case_id ?? 'unknown'}`,
    case_status:        c.state_name ?? c.case_status_name ?? c.case_status ?? 'unknown',
    case_uuid:          c.case_uuid ?? c.uuid ?? null,
    case_description:   c.case_description   ?? '',
    client_name:        c.client_name        ?? null,
    case_open_date:     c.case_open_date     ?? null,
    case_close_date:    c.case_close_date    ?? null,
    raw_case_list_item: c
  }
}));

const raw = $input.first().json.data;

if (!raw) return [{ json: { error: 'No case data found' } }];

const assets = (raw.assets ?? []).map(a => ({
  name: a.asset_name,
  type: a.type,
  ip: a.asset_ip || undefined,
  domain: a.asset_domain || undefined,
  compromised: a.asset_compromise_status,
  analysis_status: a.analysis_status,
  description: a.asset_description || undefined
}));

const iocs = (raw.iocs ?? []).map(i => ({
  type: i.type_name,
  tlp: i.tlp_name,
  description: i.ioc_description || undefined,
  tags: i.ioc_tags || undefined
}));

const timeline = (raw.timeline ?? []).map(e => ({
  date: e.event_date,
  title: e.event_title,
  category: e.category || undefined,
  content: e.event_content || undefined,
  source: e.event_source || undefined,
  flagged: e.event_is_flagged || undefined,
  assets: e.assets,
  ioc_count: (e.iocs ?? []).length
}));

const tasks = (raw.tasks ?? []).map(t => ({
  title: t.task_title,
  status: t.task_status,
  description: t.task_description || undefined,
  assignees: (t.task_assignees ?? []).map(a => a.name),
  open_date: t.task_open_date,
  close_date: t.task_close_date || undefined
}));

const notes = (raw.notes ?? []).map(n => ({
  group: n.group_title,
  title: n.note_title,
  content: (n.note_content ?? '').substring(0, 1500)
}));

const evidences = (raw.evidences ?? []).map(e => ({
  filename: e.filename,
  date_added: e.date_added,
  added_by: e.added_by
}));

const slimmed = {
  case: {
    name: raw.case?.name,
    open_date: raw.case?.open_date,
    description: raw.case?.description,
    soc_id: raw.case?.soc_id,
    opened_by: raw.case?.opened_by,
    for_customer: raw.case?.for_customer,
    status_name: raw.case?.status_name
  },
  assets,
  iocs,
  timeline: timeline.slice(0, 50),
  tasks,
  notes: notes.slice(0, 20),
  evidences,
  export_date: raw.export_date
};

return [{ json: { data: JSON.stringify(slimmed) } }];

return [{
  json: {
    case_id: $('Get Case Export').first().json.case_id,
    case_name: $('Get Case Export').first().json.case_name,
    summary: $json.output ?? $json.text ?? JSON.stringify($json)
  }
}];

const items = $input.all();

if (!items.length) {
  return [{
    json: {
      subject: 'Open Case Summary',
      body: 'No open cases were found.'
    }
  }];
}

const body = [
  '# Open Case Summary',
  '',
  `Generated: ${new Date().toISOString()}`,
  '',
  `Total open cases: ${items.length}`,
  '',
  '---',
  '',
  ...items.flatMap((item, i) => [
    `## ${i + 1}. ${item.json.case_name || `Case ${item.json.case_id || 'Unknown'}`}`,
    '',
    item.json.summary || 'No summary generated.',
    '',
    '---',
    ''
  ])
].join('\n');

return [{
  json: {
    subject: `Open Case Summary (${items.length} cases)`,
    body
  }
}];
